/* OpenStreetMap tiles and real Overpass results; no fabricated mosque locations. */
let mosqueState={lat:40.4093,lon:49.8671,zoom:14,items:[],busy:false,error:'',selected:null,origin:null,area:'',loaded:false,serial:0};
const mosqueWords={locate:['Mənə yaxın','Bana yakın','Рядом со мной','Near me','بالقرب مني'],search:['Bu ərazidə axtar','Bu bölgede ara','Искать здесь','Search this area','البحث هنا'],city:['Şəhər axtar','Şehir ara','Найти город','Find city','ابحث عن مدينة'],empty:['Bu ərazidə məscid tapılmadı. Xəritəni yaxın şəhərə çəkin.','Bu bölgede cami bulunamadı. Haritayı yakındaki bir şehre taşıyın.','Мечети не найдены. Переместите карту к городу.','No mosques found in this area. Move the map towards a city.','لم يُعثر على مساجد هنا. حرك الخريطة نحو مدينة.'],error:['Xəritə məlumatı alınmadı. İnterneti yoxlayıb yenidən sınayın.','Harita verisi alınamadı. Bağlantıyı kontrol edip tekrar deneyin.','Нет данных карты. Проверьте интернет и повторите.','Map data unavailable. Check your connection and retry.','تعذر تحميل بيانات الخريطة. تحقق من الاتصال وأعد المحاولة.'],directions:['Yol','Yol tarifi','Маршрут','Directions','الاتجاهات'],note:['Məscidlər OpenStreetMap məlumatlarına əsaslanır; nəticələr tam olmaya bilər. Məkanınız yalnız sorğu üçün istifadə olunur.','Camiler OpenStreetMap verilerine dayanır; liste eksik olabilir. Konumunuz yalnızca arama için kullanılır.','Данные OpenStreetMap могут быть неполными. Геопозиция используется только для поиска.','OpenStreetMap coverage may be incomplete. Your location is used only for this search.','قد لا تكون بيانات OpenStreetMap كاملة. يُستخدم موقعك لهذا البحث فقط.']};
function mq(k){return mosqueWords[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||mosqueWords[k]?.[0]||k}
function mosquePoint(lat,lon,z){const n=256*2**z,phi=Math.max(-85,Math.min(85,lat))*Math.PI/180;return{x:(lon+180)/360*n,y:(1-Math.log(Math.tan(phi)+1/Math.cos(phi))/Math.PI)/2*n}}
function mosqueCoords(x,y,z){const n=256*2**z;return{lon:((x/n*360+180)%360+360)%360-180,lat:Math.atan(Math.sinh(Math.PI*(1-2*y/n)))*180/Math.PI}}
function mosqueDistance(a,b){const r=Math.PI/180,dlat=(a.lat-b.lat)*r,dlon=(a.lon-b.lon)*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2))}
function mosquesPage(){if(!mosqueState.loaded){Object.assign(mosqueState,{lat:place().latitude,lon:place().longitude,loaded:true});setTimeout(findMosques,0)}setTimeout(drawMosqueMap,0);return `<div class="mosque-page" data-localized="true">${head(v16('mosques'))}<form class="mosque-result" onsubmit="event.preventDefault();mosqueCitySearch()"><input id="mosqueCity" aria-label="${mq('city')}" placeholder="${mq('city')}" maxlength="100"><button class="secondarybtn" type="submit" aria-label="${mq('city')}">${uiIcon('search')}</button></form><div id="mosqueCities"></div><div class="mosque-toolbar"><button class="goldbtn" onclick="locateMosques()">${uiIcon('location')} ${mq('locate')}</button><button class="secondarybtn" onclick="findMosques()" ${mosqueState.busy?'disabled':''}>${mq('search')}</button></div><div class="mosque-map" id="mosqueMap" data-swipe-lock="true" aria-label="OpenStreetMap"><div class="mosque-tiles"></div><div class="map-zoom"><button onclick="zoomMosques(1)" aria-label="Zoom in">+</button><button onclick="zoomMosques(-1)" aria-label="Zoom out">−</button></div><div class="map-credit">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a></div></div><p id="mosqueStatus" class="notice" role="status">${mosqueState.busy?v16('preparing'):esc(mosqueState.error)}</p><p class="notice">${esc(mosqueState.area||placeLabel())} · ${w17('distance')}</p><div class="mosque-list">${mosqueState.items.map((m,i)=>`<div class="card row"><button class="textbtn grow" onclick="openMosqueMaps(${i})"><strong>${esc(m.name)}</strong><small>${mosqueDistance(m,mosqueState.origin||mosqueState).toFixed(1)} km</small></button><button class="textbtn" onclick="openMosqueMaps(${i})" aria-label="${w17('maps')}: ${esc(m.name)}">${uiIcon('location')}</button></div>`).join('')}</div><p class="notice">${mq('note')}</p></div>`}
function drawMosqueMap(){const map=document.querySelector('#mosqueMap');if(!map)return;const s=mosqueState;if(s.fit&&s.items.length){for(let z=17;z>=10;z--){const c=mosquePoint(s.lat,s.lon,z);if(s.items.every(m=>{const p=mosquePoint(m.lat,m.lon,z);return Math.abs(p.x-c.x)<map.clientWidth*.44&&Math.abs(p.y-c.y)<map.clientHeight*.40})||z===10){s.zoom=z;break}}s.fit=false}const center=mosquePoint(s.lat,s.lon,s.zoom),w=map.clientWidth,h=map.clientHeight,tiles=map.querySelector('.mosque-tiles'),x0=center.x-w/2,y0=center.y-h/2,n=2**s.zoom;let html='';for(let x=Math.floor(x0/256);x<=Math.floor((x0+w)/256);x++)for(let y=Math.floor(y0/256);y<=Math.floor((y0+h)/256);y++){if(y<0||y>=n)continue;html+=`<img referrerpolicy="strict-origin-when-cross-origin" class="mosque-tile" alt="" draggable="false" src="https://tile.openstreetmap.org/${s.zoom}/${((x%n)+n)%n}/${y}.png" style="left:${x*256-x0}px;top:${y*256-y0}px">`}for(let i=0;i<s.items.length;i++){const m=s.items[i],p=mosquePoint(m.lat,m.lon,s.zoom),x=p.x-x0,y=p.y-y0;if(x< -20||x>w+20||y< -20||y>h+30)continue;html+=`<button class="mosque-pin ${s.selected===i?'selected':''}" style="left:${x}px;top:${y}px" aria-label="${esc(m.name)}" onclick="selectMosque(${i})">${uiIcon('location')}</button>`}tiles.innerHTML=html;
 let drag=null;map.onpointerdown=e=>{if(e.target.closest('button,a'))return;drag={x:e.clientX,y:e.clientY,c:center};map.setPointerCapture(e.pointerId)};map.onpointermove=e=>{if(!drag)return;e.preventDefault();tiles.style.transform=`translate(${e.clientX-drag.x}px,${e.clientY-drag.y}px)`};map.onpointerup=e=>{if(!drag)return;Object.assign(s,mosqueCoords(drag.c.x-(e.clientX-drag.x),drag.c.y-(e.clientY-drag.y),s.zoom));drag=null;drawMosqueMap()};map.onpointercancel=()=>{drag=null;drawMosqueMap()};}
function zoomMosques(d){mosqueState.zoom=Math.min(18,Math.max(10,mosqueState.zoom+d));drawMosqueMap()}
function selectMosque(i){const m=mosqueState.items[i];if(!m)return;Object.assign(mosqueState,{lat:m.lat,lon:m.lon,selected:i});drawMosqueMap();const box=document.querySelector('#mosqueStatus');if(box)box.textContent=m.name}
async function findMosques(){if(mosqueState.busy)return;const s=mosqueState,serial=++s.serial,center={lat:s.lat,lon:s.lon};s.origin=center;s.busy=true;s.error='';if(route==='mosques')render();try{const data=await requestMosqueData(center);if(serial!==s.serial)return;s.items=(data.elements||[]).map(m=>({lat:m.lat??m.center?.lat,lon:m.lon??m.center?.lon,name:m.tags?.['name:'+lang()]||m.tags?.name||v16('mosques')})).filter(m=>Number.isFinite(m.lat)&&Number.isFinite(m.lon)&&Math.abs(m.lat)<=90&&Math.abs(m.lon)<=180).sort((a,b)=>mosqueDistance(a,center)-mosqueDistance(b,center)).slice(0,60);s.error=s.items.length?'':mq('empty');s.fit=true}catch{s.error=mq('error')}finally{s.busy=false;if(route==='mosques')render()}}
function locateMosques(){navigator.geolocation.getCurrentPosition(p=>{Object.assign(mosqueState,{lat:p.coords.latitude,lon:p.coords.longitude,area:mq('locate')});findMosques()},()=>{toast(up('locationError'))},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}
async function mosqueCitySearch(){const input=document.querySelector('#mosqueCity'),box=document.querySelector('#mosqueCities'),name=input?.value.trim();if(!name||!box)return;box.textContent=v16('preparing');try{const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(name)}&count=5&language=${lang()}`,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const j=await r.json();box.replaceChildren();for(const p of j.results||[]){if(!Number.isFinite(p.latitude)||!Number.isFinite(p.longitude))continue;const b=document.createElement('button');b.className='row';b.textContent=[p.name,p.admin1,p.country].filter(Boolean).join(', ');b.onclick=()=>{Object.assign(mosqueState,{lat:p.latitude,lon:p.longitude,area:[p.name,p.admin1,p.country].filter(Boolean).join(', ')});findMosques()};box.append(b)}if(!box.children.length)box.textContent=mq('empty')}catch{box.textContent=mq('error')}}

const mosqueCache=new Map();
async function requestMosqueData(center){
 const lat=Math.round(center.lat*1000)/1000,lon=Math.round(center.lon*1000)/1000,id=lat+','+lon,cached=mosqueCache.get(id);if(cached&&cached.until>Date.now())return cached.data;
 try{const dx=.09/Math.max(.15,Math.cos(lat*Math.PI/180)),bbox=[Math.max(-180,lon-dx),Math.max(-85,lat-.09),Math.min(180,lon+dx),Math.min(85,lat+.09)].join(','),params=new URLSearchParams({q:'mosque',osm_tag:'amenity:place_of_worship',limit:'30',lat:String(lat),lon:String(lon),bbox});const r=await fetch('https://photon.komoot.io/api/?'+params,{signal:AbortSignal.timeout(14000)});if(!r.ok)throw Error();const j=await r.json();if(!Array.isArray(j.features))throw Error();const data={elements:j.features.map(f=>({lat:f.geometry?.coordinates?.[1],lon:f.geometry?.coordinates?.[0],tags:{name:f.properties?.name||v16('mosques')}}))};if(mosqueCache.size>60)mosqueCache.clear();mosqueCache.set(id,{until:Date.now()+900000,data});return data;}catch{const r=await fetch(SHAMS_CLOUD_CONFIG.url+'/functions/v1/nearby-mosques',{method:'POST',headers:{apikey:SHAMS_CLOUD_CONFIG.key,'Content-Type':'application/json'},body:JSON.stringify({latitude:lat,longitude:lon}),signal:AbortSignal.timeout(45000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.elements)||data.remark)throw Error();return data;}
}
